#!/usr/bin/env node
/**
 * Generate the Claude Code layer from the `.agents/` source of truth.
 *
 *   node .agents/scripts/sync_claude.mjs [--root <dir>]
 *
 * Outputs (all regenerated, do not edit by hand):
 *   CLAUDE.md                 imports the always-on rules + memory index
 *   .claude/agents/*.md       subagents (from .agents/agent)
 *   .claude/skills/<name>/    skills (from .agents/skills)
 *   .claude/commands/*.md     slash commands (from .agents/workflows)
 *   .claude/settings.json     PreToolUse safety hook
 *   .mcp.json                 MCP servers (from .agents/mcp_config.json)
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const rootArg = process.argv.indexOf('--root');
const ROOT = rootArg > -1
  ? path.resolve(process.argv[rootArg + 1])
  : path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const SRC = path.join(ROOT, '.agents');
const OUT = path.join(ROOT, '.claude');
const GENERATED = '<!-- Generated by .agents/scripts/sync_claude.mjs from .agents/ — edit the source, then run `npm run sync:claude`. -->';

const CLAUDE_TOOLS = new Set(['Read', 'Write', 'Edit', 'Bash', 'Grep', 'Glob', 'Agent', 'WebFetch', 'WebSearch', 'NotebookEdit']);

const rm = p => fs.rmSync(p, { recursive: true, force: true });
const mkdir = p => fs.mkdirSync(p, { recursive: true });
const write = (p, c) => { mkdir(path.dirname(p)); fs.writeFileSync(p, c); };

function copyDir(src, dest) {
  mkdir(dest);
  for (const e of fs.readdirSync(src, { withFileTypes: true })) {
    if (e.name === '__pycache__') continue;
    const s = path.join(src, e.name);
    const d = path.join(dest, e.name);
    if (e.isDirectory()) copyDir(s, d);
    else fs.copyFileSync(s, d);
  }
}

function splitFrontmatter(text) {
  const m = text.replace(/\r\n/g, '\n').match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  if (!m) return { fm: {}, body: text };
  const fm = {};
  for (const line of m[1].split('\n')) {
    const kv = line.match(/^([A-Za-z_-]+):\s*(.*)$/);
    if (kv) fm[kv[1]] = kv[2].trim();
  }
  return { fm, body: m[2] };
}

const csv = v => (v || '').split(',').map(s => s.trim()).filter(Boolean);
const yamlStr = v => JSON.stringify(v.replace(/^["']|["']$/g, ''));

// ── skills ──────────────────────────────────────────────────────────────────
const skillsSrc = path.join(SRC, 'skills');
rm(path.join(OUT, 'skills'));
const skillNames = new Set();
for (const e of fs.readdirSync(skillsSrc, { withFileTypes: true })) {
  if (!e.isDirectory() || !fs.existsSync(path.join(skillsSrc, e.name, 'SKILL.md'))) continue;
  copyDir(path.join(skillsSrc, e.name), path.join(OUT, 'skills', e.name));
  skillNames.add(e.name);
}

// ── agents ──────────────────────────────────────────────────────────────────
rm(path.join(OUT, 'agents'));
let agentCount = 0;
for (const f of fs.readdirSync(path.join(SRC, 'agent')).filter(f => f.endsWith('.md'))) {
  const { fm, body } = splitFrontmatter(fs.readFileSync(path.join(SRC, 'agent', f), 'utf8'));
  const tools = csv(fm.tools).filter(t => CLAUDE_TOOLS.has(t));
  const skills = csv(fm.skills).filter(s => skillNames.has(s));
  const lines = ['---', `name: ${fm.name || f.replace(/\.md$/, '')}`, `description: ${yamlStr(fm.description || '')}`];
  if (tools.length) lines.push(`tools: ${tools.join(', ')}`);
  if (fm.model) lines.push(`model: ${fm.model}`);
  if (skills.length) lines.push('skills:', ...skills.map(s => `  - ${s}`));
  lines.push('---', GENERATED, '', body.trimStart());
  write(path.join(OUT, 'agents', f), lines.join('\n'));
  agentCount++;
}

// ── commands (workflows) ────────────────────────────────────────────────────
rm(path.join(OUT, 'commands'));
let cmdCount = 0;
const wfDir = path.join(SRC, 'workflows');
for (const f of fs.existsSync(wfDir) ? fs.readdirSync(wfDir).filter(f => f.endsWith('.md')) : []) {
  const { fm, body } = splitFrontmatter(fs.readFileSync(path.join(wfDir, f), 'utf8'));
  const out = ['---', `description: ${yamlStr(fm.description || f)}`, 'argument-hint: "[request]"', '---', GENERATED, '', body.trimStart(), '', 'User request: $ARGUMENTS', ''];
  write(path.join(OUT, 'commands', f), out.join('\n'));
  cmdCount++;
}

// ── settings (hooks) ────────────────────────────────────────────────────────
write(path.join(OUT, 'settings.json'), JSON.stringify({
  hooks: {
    PreToolUse: [{
      matcher: 'Bash',
      hooks: [{ type: 'command', command: 'node "$CLAUDE_PROJECT_DIR/.agents/hooks/validate-tool-call.mjs"', timeout: 10 }]
    }]
  }
}, null, 2) + '\n');

// ── MCP ─────────────────────────────────────────────────────────────────────
const mcpSrc = path.join(SRC, 'mcp_config.json');
if (fs.existsSync(mcpSrc)) write(path.join(ROOT, '.mcp.json'), fs.readFileSync(mcpSrc, 'utf8'));

// ── CLAUDE.md ───────────────────────────────────────────────────────────────
const rulesDir = path.join(SRC, 'rules');
const always = [];
const onDemand = [];
for (const f of fs.readdirSync(rulesDir).filter(f => f.endsWith('.md')).sort()) {
  const { fm } = splitFrontmatter(fs.readFileSync(path.join(rulesDir, f), 'utf8'));
  (fm.trigger === 'always_on' ? always : onDemand).push({ f, desc: fm.description || '' });
}
const claudeMd = [
  GENERATED,
  '# Agent Template (Claude Code)',
  '',
  'This repo uses the AG Kit toolkit. `.agents/` is the source of truth; `.claude/` is generated from it.',
  'Subagents: `.claude/agents/`. Skills: `.claude/skills/`. Slash commands (`/plan`, `/commit`, `/orchestrate`, …): `.claude/commands/`.',
  'Where rules say `.agents/skills/...`, the same skill is also installed as a native skill under `.claude/skills/`.',
  '',
  '## Always-on rules',
  ...always.map(r => `@.agents/rules/${r.f}`),
  '',
  '## Memory',
  '@.agents/memory/MEMORY.md',
  '',
  '## Read on demand',
  ...onDemand.map(r => `- \`.agents/rules/${r.f}\`${r.desc ? ` — ${r.desc}` : ''}`),
  ''
].join('\n');
write(path.join(ROOT, 'CLAUDE.md'), claudeMd);

console.log(`Claude layer generated: ${agentCount} agents, ${skillNames.size} skills, ${cmdCount} commands.`);
